(* [comment removed for export] *)
Definition rs_ms (pc : Z) (rax : word) (sp : word) (spa : Z) (gp tp t0 t1 t2 : word) (E : Z) (a0 a1 a2 a3 a4 a5 a6 a7 : word)
    (tot fb ff : Z) (s5x s6x : word) (t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) : machine_state :=
  MS (mkR rax (wz spa) gp tp t0 t1 t2 sp (wz spa) a0 a1 a2 a3 a4 a5 a6 a7
          (wz (ff + 96)) (wz (ff + 32)) (wz E) s5x s6x (wz (Z.shiftr ff 3 + 2147450880)) (wz fb) (wz 2147450880)
          (wz (fb + 16)) (wz tot) t3 t4 t5 t6)
     F (Z_to_bv 64 pc) fc None m (seg_rom bsegs).

Definition rs_sv (s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra : word) : list cell :=
  [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

(* [comment removed for export] *)
Definition rs_shcells (ob eb : Z) : list cell :=
  [CB 4 [b8 241; b8 241; b8 241; b8 241]; C1 (b8 ob); C1 (b8 ob); C1 (b8 ob); C1 (b8 242);
   CB 4 [b8 242; b8 242; b8 242; b8 242]; C1 (b8 eb); C1 (b8 eb); C1 (b8 eb); C1 (b8 243);
   CB 4 [b8 243; b8 243; b8 243; b8 243]; CB 12 (repeat (b8 0) 12)].

(* [comment removed for export] *)
Ltac rw_split K k K1 K2 a2 :=
  lazymatch type of K with rw_cells ?segs ?m ?a ?cs =>
    let l1 := eval cbn [firstn] in (firstn k cs) in let l2 := eval cbn [skipn] in (skipn k cs) in
    pose proof (proj1 (rw_cells_app segs m a l1 l2) K) as [K1 K2];
    lazymatch type of K2 with rw_cells _ _ ?ad _ => replace ad with a2 in K2 by (cbn [cells_size csize Nat.add app length]; lia) end; clear K end.

Lemma rw_cells_nil0 : forall m A, 0 <= A <= 2^64 -> rw_cells bsegs m A [].
Proof.
  intros m A HA. split; [split; [exact I|]|].
  - split; [lia|]. split; [cbn; lia|]. intros i Hi. cbn in Hi. lia.
  - split; [lia|]. split; [cbn; lia|]. intros i Hi. cbn in Hi. lia.
Qed.

Section HCW.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Hypothesis FS2 : stack_malloc_2_stmt H.

(* [comment removed for export] *)
Definition rs_frame (m : mem) (sp : word) (spa ff E bs P fb : Z) (mw80 : cell) (tmp gap : list cell) : Prop :=
     (exists jl, rw_cells bsegs m spa [CB 16 jl])
  /\ rw_cells bsegs m (spa + 16) [C8 (wz ff); C8 (wz ff); C8 (wz (ff + 32)); C8 (wz fb); C8 (wz bs); C8 (wz (Z.shiftr (fb + 8) 3 + 2147450880));
                                 C8 (wz P); C8 (wz (fb + 8))]
  /\ rw_cells bsegs m (spa + 80) [mw80] /\ csize mw80 = 8%nat /\ rw_cells bsegs m (spa + 88) [C8 (wz (Z.shiftr (fb + 16) 3 + 2147450880))]
  /\ (exists j96, rw_cells bsegs m (spa + 96) [CB 24 j96]) /\ rw_cells bsegs m (spa + 120) [C8 (wz ff)]
  /\ rw_cells bsegs m (spa + 128) tmp /\ cells_size tmp = 24%nat
  /\ rw_cells bsegs m (spa + 152) gap /\ Z.of_nat (cells_size gap) = bv_unsigned sp + -104 - (spa + 152)
  /\ (spa = bv_unsigned sp + -256 \/ spa = bv_unsigned sp + -272).

(* [comment removed for export] *)
Definition rs_fake (m : mem) (ff fp : Z) (hw : word) (optc : list cell) (j56 : list byte) (ectc : list cell) (j120 : list byte) (ob eb : Z) : Prop :=
     rw_cells bsegs m ff [C8 (wz AFMAGIC); C8 (wz ADESCR_RS); C8 (wz P_A_HTTP_READ_SOME); C8 hw]
  /\ rw_cells bsegs m (ff + 32) optc /\ cells_size optc = 24%nat
  /\ rw_cells bsegs m (ff + 56) [CB 40 j56]
  /\ rw_cells bsegs m (ff + 96) ectc /\ cells_size ectc = 24%nat
  /\ rw_cells bsegs m (ff + 120) [CB 128 j120]
  /\ rw_cells bsegs m (ff + 248) [C8 (wz fp)]
  /\ rw_cells bsegs m (Z.shiftr ff 3 + 2147450880) (rs_shcells ob eb)
  /\ rw_cells bsegs m fp [C1 (b8 1)].

