(* [comment removed for export] *)
Definition win_fs2 (ff : Z) (iv : Z * Z) : Prop :=
  snd iv <= ALOWSH_LO \/ AHI_LO <= fst iv \/ (fst iv = Z.shiftr ff 3 + 2147450880 /\ snd iv = Z.shiftr ff 3 + 2147450880 + 32).

Lemma win_fs2_fr : forall LF ff fp W, fresh_frame H LF 2 ff fp -> Forall (win_fs2 ff) W -> Forall (win_fr ff 32) W.
Proof.
  intros LF ff fp W FF FW.
  pose proof (ff_facts _ _ _ _ _ FF) as (_ & _ & _ & _ & F1 & F2 & F3 & _ & F4 & F5 & F6 & F7 & F8 & F9 & F10 & F11 & F12 & APF & APP1 & SHFF & _).
  eapply Forall_impl; [| exact FW]. intros [l h] K. unfold win_fs2, win_fr in *. cbn [fst snd] in *. rewrite <- SHFF. lia.
Qed.
