(* [comment removed for export] *)
Lemma addressable_fs2 : forall ff fp LF m0 m1 m2 O n W,
  as_RFS H LF m0 -> fresh_frame H LF 2 ff fp -> fsobj H LF O n -> aapp O n -> 0 <= n -> addressable m1 O n ->
  munch W m1 m2 -> wmono bsegs m1 m2 -> Forall (win_fs2 ff) W -> addressable m2 O n.
Proof.
  intros ff fp LF m0 m1 m2 O n W RF FF FO AP N0 AD MU WM FW.
  pose proof (aapp_bounds _ _ AP N0) as (B1 & B2 & B3 & B4 & B5).
  pose proof (ff_facts _ _ _ _ _ FF) as (_ & _ & _ & _ & F1 & F2 & F3 & _ & F4 & F5 & F6 & F7 & F8 & F9 & F10 & F11 & F12 & APF & APP1 & SHFF & _).
  pose proof (fsobj_windows _ HH _ _ _ _ _ _ _ RF FO FF ltac:(lia) N0 ltac:(lia)) as (_ & D2 & _). change (fshn 2) with 32 in D2. rewrite <- SHFF in D2.
  pose proof (sh_ge_lowsh O ltac:(lia)) as KL. pose proof (sh_nsh_high O n ltac:(lia) N0 ltac:(lia)) as KH.
  eapply addressable_transport; [exact AD| exact MU| exact WM|].
  clear - FW D2 KL KH. induction W as [|[l h] W IH]; [exact I|]. cbn [disjoint_from fst snd]. split; [| exact (IH (Forall_inv_tail FW))].
  pose proof (Forall_inv FW) as F1. unfold win_fs2 in F1. cbn [fst snd] in F1. destruct F1 as [F1|[F1|[-> ->]]]; lia.
Qed.

(* [comment removed for export] *)
Lemma accessible_fs2 : forall ff fp LF m0 m1 m2 O n a k W,
  as_RFS H LF m0 -> fresh_frame H LF 2 ff fp -> fsobj H LF O n -> 0 <= O -> 0 <= n -> O + n <= AAPP_HI -> O <= a -> a + k <= O + n ->
  accessible m1 a k -> munch W m1 m2 -> Forall (win_fs2 ff) W -> accessible m2 a k.
Proof.
  intros ff fp LF m0 m1 m2 O n a k W RF FF FO O0 N0 OH A1 A2 AC MU FW.
  pose proof (fsobj_windows _ HH _ _ _ _ _ _ _ RF FO FF O0 N0 OH) as (D1 & _). change (fsz 2) with 256 in D1.
  pose proof (ff_facts _ _ _ _ _ FF) as (_ & _ & _ & _ & F1 & F2 & F3 & _).
  eapply (accessible_transport_fr _ _ _ a k ff 32); [exact AC| exact MU| eapply win_fs2_fr; [exact FF| exact FW]| unfold AIMG_TOP, AFS_HDR in F1; lia| exact F3| lia| lia].
Qed.

(* [comment removed for export] *)
Lemma AFlatBuf_fs2 : forall ff fp LF m0 m1 m2 LB a F ds W,
  as_RFS H LF m0 -> fresh_frame H LF 2 ff fp ->
  AFlatBuf LB m1 a F ds -> (F <> FB_empty -> fsobj H LF (fb_begin F) (fb_cap F)) ->
  munch W m1 m2 -> wmono bsegs m1 m2 -> Forall (win_fs2 ff) W ->
  disjoint_from W a SZ_FB -> (F <> FB_empty -> disjoint_from W (fb_begin F) (fb_cap F)) ->
  AFlatBuf LB m2 a F ds.
Proof.
  intros ff fp LF m0 m1 m2 LB a F ds W RF FF FB FOF MU WM FW D DB.
  pose proof (ff_facts _ _ _ _ _ FF) as (_ & _ & _ & _ & F1 & F2 & F3 & _ & F4 & F5 & F6 & F7 & F8 & F9 & F10 & F11 & F12 & APF & APP1 & SHFF & _).
  eapply AFlatBuf_transport; [exact FB| exact MU| exact WM| exact D| exact DB|].
  intros NE. destruct FB as (_ & FOK & _). destruct FOK as [E|(q & INq & RBq & CAP & _)]; [contradiction|].
  pose proof (rblock_bounds _ _ RBq) as (C1 & C2 & C3 & C4 & C5 & C6). pose proof RBq as (_ & _ & _ & APq & _).
  pose proof (fsobj_windows _ HH _ _ _ _ _ _ _ RF (FOF NE) FF C1 ltac:(lia) C3) as (_ & E2 & _). change (fshn 2) with 32 in E2. rewrite <- SHFF in E2.
  pose proof (sh_ge_lowsh (fb_begin F) C1) as KL. pose proof (sh_nsh_high (fb_begin F) (fb_cap F) C1 ltac:(lia) C3) as KH.
  clear - FW E2 KL KH. induction W as [|[l h] W IH]; [exact I|]. cbn [disjoint_from fst snd]. split; [| exact (IH (Forall_inv_tail FW))].
  pose proof (Forall_inv FW) as K. unfold win_fs2 in K. cbn [fst snd] in K. destruct K as [K|[K|[-> ->]]]; lia.
Qed.

