(* [comment removed for export] *)
Definition rs_entry_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LF : list fframe) (lo shi E bs fb P : Z) (FB : fbv) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m' (spa ff fp : Z) (jm jt : list byte) (gap : list cell) (hw : word) (j56 j120 jo je : list byte)
