(* [comment removed for export] *)
(* [comment removed for export] *)
Definition rs_retd_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LF : list fframe) (lo shi ff fp tot : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0' a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz tot) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc ra) fc None m' (seg_rom bsegs)
      /\ a0' = wz tot
      /\ munch [(ff, ff + 8); (Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147450880 + 32); (fp, fp + 1)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
      /\ stk bsegs m' lo (bv_unsigned sp)
      /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.

Lemma rs_ret : forall rax sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s5x s6x t3 t4 t5 t6
    (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v ra : word)
    (F : bvmap 5 word) fc (m : mem) (LF : list fframe) (lo shi spa ff fp E bs fb P tot ob eb : Z) (hw : word)
    (mw80 : cell) (tmp gap optc ectc : list cell) (j56 j120 : list byte),
  rs_frame m sp spa ff E bs P fb mw80 tmp gap ->
  rw_cells bsegs m (bv_unsigned sp + -104) (rs_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) ->
